// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }
    function testFuzz_property(address caller, address newDao) public {
        // Admissible domain: caller should be a non-DAO address and newDao non-zero
        address oldDao = c.DAO();
        vm.assume(caller != address(0));
        vm.assume(caller != oldDao);
        vm.assume(newDao != address(0));
        vm.assume(newDao != oldDao);

        // Configure the contract so `configured` is true; DAO is set in setUp to the stub
        c.endConfiguration();

        // Snapshot DAO before call
        address daoBefore = c.DAO();

        // Attempt the unauthorized setDAO from `caller`
        vm.prank(caller);
        bool ok = true;
        try c.setDAO(newDao) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an unauthorized caller must NOT be able to change DAO.
        // Reference: either the call reverts OR DAO remains unchanged.
        // Mutant: call succeeds and overwrites DAO, so (ok && daoAfter != daoBefore) is true.
        address daoAfter = c.DAO();
        assertTrue(!(ok && daoAfter != daoBefore));
    }
}

